using System;
using System.Collections.Generic;
using System.Diagnostics;
using SkiaSharp;

namespace Gum;

/// <summary>SPIKE (#8098): flush breakdown. GUM_FLUSHPROBE=1 splits target.End into flush/submit; GUM_GLTIME=1 times every
/// integer-argument GL call Skia makes, per name; GUM_CTXOPT sets GRContextOptions variants; GUM_OWNPASS=1 with GUM_RESET=none|all.</summary>
public static unsafe class FlushProbe
{
    public static readonly bool Enabled = Environment.GetEnvironmentVariable("GUM_FLUSHPROBE") == "1";
    public static readonly bool NoDraw = Environment.GetEnvironmentVariable("GUM_NODRAW") == "1";
    public static readonly bool GlTime = Environment.GetEnvironmentVariable("GUM_GLTIME") == "1";
    public static readonly string? CtxOpt = Environment.GetEnvironmentVariable("GUM_CTXOPT");
    public static readonly bool OwnPass = Environment.GetEnvironmentVariable("GUM_OWNPASS") == "1";
    public static readonly string? Reset = Environment.GetEnvironmentVariable("GUM_RESET");
    public static readonly bool Defer = Environment.GetEnvironmentVariable("GUM_DEFERSUBMIT") == "1";

    // GUM_RAW=N: N plain-SkiaSharp ops (half DrawImageLattice, half text blobs) on the same canvas, no Gum code. Run with --region empty.
    public static readonly int Raw = int.TryParse(Environment.GetEnvironmentVariable("GUM_RAW"), out int raw) ? raw : 0;
    static SKImage? _rawImage;
    static SKTextBlob?[]? _rawBlobs;
    static SKPaint? _rawPaint, _textPaint;
    public static void DrawRaw(SKCanvas canvas)
    {
        if (_rawImage == null)
        {
            using var bmp = new SKBitmap(24, 24);
            using (var c = new SKCanvas(bmp)) { c.Clear(SKColors.DarkSlateGray); using var p = new SKPaint { Color = SKColors.LightGray }; c.DrawRect(4, 4, 16, 16, p); }
            _rawImage = SKImage.FromBitmap(bmp).ToTextureImage(GlTargetGr!);
            using var font = new SKFont(SKTypeface.Default, 16);
            _rawBlobs = new SKTextBlob?[100];
            for (int i = 0; i < 100; i++) _rawBlobs[i] = SKTextBlob.Create(i.ToString(), font);
            _rawPaint = new SKPaint(); _textPaint = new SKPaint { Color = SKColors.White, IsAntialias = true };
        }
        var lattice = new SKLattice { XDivs = new[] { 8, 16 }, YDivs = new[] { 8, 16 } };
        bool grouped = Environment.GetEnvironmentVariable("GUM_RAWGROUPED") == "1";
        for (int pass = 0; pass < (grouped ? 2 : 1); pass++)
        for (int i = 0; i < Raw / 2; i++)
        {
            int cell = i % 100; float x = 710 + (cell % 10) * 56, y = 8 + (cell / 10) * 40;
            if (!grouped || pass == 0) canvas.DrawImageLattice(_rawImage, lattice, new SKRect(x, y, x + 52, y + 36), SKFilterMode.Linear, _rawPaint);
            if (!grouped || pass == 1) canvas.DrawText(_rawBlobs![cell], x + 8, y + 24, _textPaint);
        }
    }
    public static GRContext? GlTargetGr;

    // per frame: begin, record, flush, submit, endRest
    public static readonly List<double[]> Frames = new();
    public static long BeginStart, BeginEnd, FlushStart, FlushEnd, SubmitEnd, EndEnd;
    public static double ToMs = 1000.0 / Stopwatch.Frequency;

    public static void FrameDone()
    {
        Frames.Add(new[] { (BeginEnd - BeginStart) * ToMs, (FlushStart - BeginEnd) * ToMs, (FlushEnd - FlushStart) * ToMs,
            (SubmitEnd - FlushEnd) * ToMs, (EndEnd - SubmitEnd) * ToMs });
        if (GlTime)
        {
            for (int i = 0; i < Count; i++) { FrameTicks[i].Add(Ticks[i]); FrameCalls[i].Add(Calls[i]); Ticks[i] = 0; Calls[i] = 0; }
        }
    }

    static double Median(IEnumerable<double> v) { var a = new List<double>(v); a.Sort(); return a.Count == 0 ? 0 : a[a.Count / 2]; }

    public static void Report(int lastFrames)
    {
        if (Frames.Count == 0) return;
        var last = Frames.GetRange(Math.Max(0, Frames.Count - lastFrames), Math.Min(lastFrames, Frames.Count));
        string[] names = { "Begin(reset+query)", "record", "gr.Flush(no submit)", "gr.Submit", "SGR End rest" };
        for (int s = 0; s < names.Length; s++)
            Console.WriteLine($"PROBE {names[s]}: median {Median(last.ConvertAll(f => f[s])):F3} ms");
        if (!GlTime) return;
        var rows = new List<(string name, double ms, double calls)>();
        double total = 0, totalCalls = 0;
        for (int i = 0; i < Count; i++)
        {
            int n = FrameTicks[i].Count; int from = Math.Max(0, n - lastFrames);
            double sumT = 0, sumC = 0;
            for (int f = from; f < n; f++) { sumT += FrameTicks[i][f]; sumC += FrameCalls[i][f]; }
            int frames = n - from; if (frames == 0) continue;
            double ms = sumT * ToMs / frames, calls = sumC / frames;
            if (calls > 0) { rows.Add((Names[i], ms, calls)); total += ms; totalCalls += calls; }
        }
        rows.Sort((a, b) => b.ms.CompareTo(a.ms));
        Console.WriteLine($"GLTIME total inside GL per frame (mean): {total:F3} ms over {totalCalls:F0} calls");
        foreach (var r in rows) Console.WriteLine($"GLTIME {r.name}: {r.ms:F4} ms, {r.calls:F1} calls/frame");
    }

    // ---- generic GL wrappers (integer/pointer args only, up to 10) ----
    const int Max = 400;
    static int Count;
    static readonly IntPtr[] Real = new IntPtr[Max];
    static readonly string[] Names = new string[Max];
    static readonly long[] Ticks = new long[Max];
    static readonly long[] Calls = new long[Max];
    static readonly List<long>[] FrameTicks = new List<long>[Max];
    static readonly List<long>[] FrameCalls = new List<long>[Max];
    static readonly HashSet<string> FloatArgs = new() { "glUniform1f","glUniform2f","glUniform3f","glUniform4f","glTexParameterf","glClearColor",
        "glBlendColor","glLineWidth","glClearDepth","glClearDepthf","glDepthRange","glDepthRangef","glPolygonOffset","glPointSize","glSampleCoverage",
        "glMinSampleShading","glClearBufferfi","glVertexAttrib1f","glVertexAttrib2f","glVertexAttrib3f","glVertexAttrib4f","glPathParameterf",
        "glTexParameterfv" /*pointer, fine but keep*/ };

    public static IntPtr Wrap(string name, IntPtr real)
    {
        if (!GlTime || real == IntPtr.Zero || FloatArgs.Contains(name) || Count >= Max) return real;
        int i = Count++;
        Real[i] = real; Names[i] = name; FrameTicks[i] = new List<long>(); FrameCalls[i] = new List<long>();
        return Tramp(i);
    }

    static nint Call(int i, nint a, nint b, nint c, nint d, nint e, nint f, nint g, nint h, nint j, nint k)
    {
        long t = Stopwatch.GetTimestamp();
        nint r = ((delegate* unmanaged<nint, nint, nint, nint, nint, nint, nint, nint, nint, nint, nint>)Real[i])(a, b, c, d, e, f, g, h, j, k);
        Ticks[i] += Stopwatch.GetTimestamp() - t; Calls[i]++;
        return r;
    }
